package com.cob.emr.ddd.domain.medicalnote.model.assessment;import com.cob.emr.ddd.domain.medicalnote.model.valueobjects.GoalType;import com.cob.emr.ddd.domain.medicalnote.model.valueobjects.TimePeriod;import lombok.Builder;import lombok.Getter;@Getter@Builder(toBuilder = true)public class FunctionalGoal {    private final String term;    private final String period;    private final String customPeriod;    private final String description;    private final String met;    private final String customMet;        public void validate() {        if (description == null || description.trim().isEmpty()) {            throw new IllegalStateException("Goal description is required");        }    }        public GoalType getGoalType() {        if ("Short Term".equalsIgnoreCase(term)) {            return GoalType.SHORT_TERM;        } else if ("Long Term".equalsIgnoreCase(term)) {            return GoalType.LONG_TERM;        }        return GoalType.SHORT_TERM;    }        public TimePeriod getTimePeriod() {        return TimePeriod.fromString(period);    }        public int getProgressPercentage() {        if (met == null || met.trim().isEmpty()) return 0;        try {            String cleaned = met.replace("%", "").trim();            return Integer.parseInt(cleaned);        } catch (NumberFormatException e) {            return 0;        }    }        public boolean isMet() {        return getProgressPercentage() >= 80;    }        public FunctionalGoal updateProgress(String newProgress) {        return this.toBuilder()            .met(newProgress)            .build();    }}
